						pos = Math.min(this._nextLt, this._nextAmp, this._nextNul);
						// Fused: the memo invariant guarantees `input[nextLt] === "<"`, so
						// take this state's `<` arc without another dispatch.
						if (pos !== this._nextLt || pos >= len) break;
						this._tagStart = pos;
